import { ENV_CONFIG } from '../config/env';
import { API_ENDPOINTS } from '../services/api/endpoints';
import { FloorSelector } from './FloorSelector';
import { Icon } from './Icon';
import { useAppStore } from '../store/appStore';
import type { Project } from '../domain/project';

/**
 * PlanViewer renders the architectural floor plan generated by the backend
 * (`plan.svg` — walls, openings, shafts, dimensions). It is a pure artifact
 * view: the interactive layout editor remains the LotViewer.
 */
export function PlanViewer({ project }: { project: Project }) {
  const activeFloor = useAppStore((s) => s.activeFloor);
  const url = `${ENV_CONFIG.API_BASE_URL}${API_ENDPOINTS.projectPlanSvg(project.id, activeFloor)}`;
  const issues = (project.room_schedule?.issues ?? []).filter(
    (i) => i.floor === activeFloor || i.floor === undefined,
  );

  return (
    <section className="bg-surface-container-lowest border border-outline-variant rounded-2xl p-space-lg shadow-elevation-1">
      <header className="flex flex-wrap items-center justify-between gap-3 mb-4">
        <div className="flex items-center gap-2">
          <Icon name="architecture" className="text-[20px] text-primary" />
          <div>
            <h3 className="text-title-md font-title-md font-bold text-on-surface">Planta Baixa</h3>
            <p className="text-label-sm text-on-surface-variant">
              Gerada no backend — paredes {Math.round((project.wall_thickness || 0.15) * 100)} cm, aberturas, shafts e cotas (estimativa educacional)
            </p>
          </div>
        </div>
        <FloorSelector project={project} compact />
      </header>

      <div className="rounded-xl border border-outline-variant bg-surface overflow-x-auto">
        <img
          src={url}
          alt={`Planta baixa — pavimento ${activeFloor}`}
          className="max-w-none w-full min-w-[560px]"
        />
      </div>

      {issues.length > 0 && (
        <ul className="mt-3 space-y-1">
          {issues.map((i, idx) => (
            <li
              key={idx}
              className={`flex items-start gap-2 text-[12px] rounded-lg px-3 py-2 ${
                i.severity === 'error'
                  ? 'bg-error-container/60 text-on-error-container'
                  : 'bg-secondary-container/50 text-on-secondary-container'
              }`}
            >
              <Icon name={i.severity === 'error' ? 'error' : 'warning'} className="text-[15px] mt-px" />
              <span>
                <code className="font-mono text-[10px] opacity-70 mr-1">{i.code}</code>
                {i.message}
              </span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
